import{_ as r,h as o,i as t,c as s,v as e,p as n,x as l,m as p,e as d,S as h}from"./chunks/framework.Dvtg8yj2.js";const b=JSON.parse('{"title":"Rectified flow 潜空间扩散","description":"","frontmatter":{"title":"Rectified flow 潜空间扩散","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/atlas-rectified-flow.md","filePath":"llm/atlas-rectified-flow.md","lastUpdated":1788454257000}'),m={name:"llm/atlas-rectified-flow.md"};function c(E,a,_,A,D,f){const i=o("Mermaid");return t(),s("div",null,[a[1]||(a[1]=e('<h1 id="rectified-flow-潜空间扩散" tabindex="-1">Rectified flow 潜空间扩散 <a class="header-anchor" href="#rectified-flow-潜空间扩散" aria-label="Permalink to &quot;Rectified flow 潜空间扩散&quot;">​</a></h1><div class="epigraph"><p>连续外观在压缩后的潜变量里沿近似直线的速度场从噪声流向数据；步数可以换质量，而不必在像素上跑完离散马尔可夫链。</p><footer>—— Lipman et al., Flow Matching for Generative Modeling, 2023；Atlas 称自身为 rectified flow 的潜扩散模型</footer></div><p>Atlas 的扩散一词有两层公开含义。第一，它是 rectified flow 模型，用逐步去噪生成高维连续数据，推理时可用步数换质量。第二，它是 latent diffusion model，去噪发生在 VAE 潜空间，并可使用蒸馏、CFG、偏移噪声日程与 VAE 进展。World Labs 没有为 Atlas 发表带 arXiv 编号的技术报告；整流流与流匹配的公式应回到 Lipman 等人 2023 年的工作（以及同期把路径拉直的整流流叙述），潜空间扩散回到 Rombach 等人的 LDM，离散时间去噪对照 Ho 等人的 DDPM。本篇只写这条生成内核，不把 Atlas 的层数写进不存在的论文。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>图像与深度不能像词一样做 softmax。DDPM 把数据逐步加高斯噪声到近似先验，再学反向去噪：</p> \\[q(x_t\\mid x_0)=\\mathcal{N}\\bigl(x_t;\\sqrt{\\bar\\alpha_t}x_0,(1-\\bar\\alpha_t)I\\bigr). \\]<p>这条链在像素上算力极高。LDM 的回答是先把 \\(x\\) 编成 \\(z=\\mathcal{E}(x)\\)，在 \\(z\\) 上扩散，解码 \\(\\mathcal{D}(z)\\)。世界模型还要在潜空间里条件于空间上下文与相机，并且推理步数必须可调：展示用多步，产品用少步。标准 DDPM 的弯曲采样轨迹使少步时误差大，于是需要更直的流。</p><p>整流流 / 流匹配把生成看成沿时间 \\(t\\in[0,1]\\) 的常微分方程，而不是必须五十到一千步的马尔可夫链。目标是学速度场，使粒子从噪声走到数据。路径越直，少步欧拉积分越准，也越适合蒸馏。</p><h3 id="潜空间与整流流解决的不是同一件事" tabindex="-1">潜空间与整流流解决的不是同一件事 <a class="header-anchor" href="#潜空间与整流流解决的不是同一件事" aria-label="Permalink to &quot;潜空间与整流流解决的不是同一件事&quot;">​</a></h3><p>潜空间降低的是每步的维数与感受野设计难度（感知压缩把高频交给解码器）。整流流改善的是从先验到数据的路径几何。可以在像素上做整流流，也可以在潜空间做 DDPM；Atlas 声明二者都要。缺少任何一侧，要么 1440p 算不起，要么少步时结构塌。</p><p><span class="marginnote">「Atlas 是整流流」不等于公开了具体的 \\(t\\) 采样、是否 OT 耦合、CFG 加在速度上还是噪声上。那些是实现选择。本篇写公开代数，不写虚构超参。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>流匹配把条件路径定为从数据 \\(z_0\\) 到噪声 \\(z_1\\) 的插值。一条直线（最优传输条件流、与整流流叙述一致的形式）是</p> \\[z_t=(1-t)z_0+t z_1,\\qquad u_t(z_t\\mid z_0,z_1)=z_1-z_0. \\]<p>网络 \\(v_\\theta(z_t,t,c)\\) 条件于空间上下文 \\(c\\)（含位姿与参考潜变量），回归 \\(u_t\\)。训练目标为</p> \\[\\mathcal{L}=\\mathbb{E}\\bigl\\|v_\\theta(z_t,t,c)-(z_1-z_0)\\bigr\\|_2^2. \\]<p>推理从 \\(z_1\\sim\\mathcal{N}(0,I)\\) 积 \\(\\mathrm{d}z=v_\\theta\\mathrm{d}t\\) 到 \\(t=0\\)，再 \\(\\hat x=\\mathcal{D}(z_0)\\)。步数 \\(N\\) 就是把 \\([0,1]\\) 切成 \\(N\\) 段。Atlas 所说「用去噪步数换速度与质量」，在这条 ODE 上就是 \\(N\\) 的选择。蒸馏则学一个更少步仍近似同一终点的学生场。</p><p>CFG（Ho &amp; Salimans）在扩散里把有条件与无条件预测外推。对速度场可以写成</p> \\[\\tilde v=v_{\\emptyset}+s\\bigl(v_c-v_{\\emptyset}\\bigr), \\]<p>\\(s&gt;1\\) 加强文本或参考服从。这是家族技巧；Atlas 只说可以使用，没有给出 \\(s\\) 的默认值。</p>',20)),(t(),n(h,null,{default:l(()=>[d(i,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20LR%0A%20%20X%5B%22%E5%83%8F%E7%B4%A0%20%2F%20%E6%B7%B1%E5%BA%A6%22%5D%20--%3E%20E%5B%22VAE%20%E7%BC%96%E7%A0%81%E5%99%A8%22%5D%0A%20%20E%20--%3E%20Z%5B%22%E6%BD%9C%E5%8F%98%E9%87%8F%20z%22%5D%0A%20%20C%5B%22%E7%A9%BA%E9%97%B4%E4%B8%8A%E4%B8%8B%E6%96%87%E4%B8%8E%E4%BD%8D%E5%A7%BF%22%5D%20--%3E%20V%5B%22%E9%80%9F%E5%BA%A6%E5%9C%BA%20v_theta%22%5D%0A%20%20Z%20--%3E%20V%0A%20%20N%5B%22%E5%99%AA%E5%A3%B0%20z_1%22%5D%20--%3E%20ODE%5B%22%E6%B2%BF%E6%95%B4%E6%B5%81%E8%B7%AF%E5%BE%84%E7%A7%AF%E5%88%86%22%5D%0A%20%20V%20--%3E%20ODE%0A%20%20ODE%20--%3E%20D%5B%22VAE%20%E8%A7%A3%E7%A0%81%22%5D%0A%20%20D%20--%3E%20Y%5B%22%E8%BE%93%E5%87%BA%E5%85%83%E7%B4%A0%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h3 id="与-ddpm-的对照" tabindex="-1">与 DDPM 的对照 <a class="header-anchor" href="#与-ddpm-的对照" aria-label="Permalink to &quot;与 DDPM 的对照&quot;">​</a></h3><p>DDPM 学的是噪声 \\(\\varepsilon_\\theta\\) 或 \\(x_0\\) 预测，采样是离散反向链。整流流学速度，采样是 ODE。经验上直线路径在少步时更稳，这是视频与世界模型愿意换到 flow 的原因。LDM 与二者正交：无论 \\(\\varepsilon\\) 还是 \\(v\\)，都可以在 \\(z\\) 上算。Rombach 等人证明高分辨率生成的瓶颈往往在像素扩散，不在骨干姓 Transformer 还是 U-Net。Atlas 的骨干是 Transformer，潜空间仍然必要，否则每个视觉元素的 token 数按像素计。</p><p><span class="marginnote">偏移噪声日程、感知压缩的下采样倍数、潜维，博客均未给出。写「Atlas 使用与 SD3 相同的 VAE」是猜测。只能写：它宣称自己是潜扩散，因而与 VAE 设计进展兼容。</span></p><h3 id="条件出现在速度场里而不是事后warp" tabindex="-1">条件出现在速度场里而不是事后warp <a class="header-anchor" href="#条件出现在速度场里而不是事后warp" aria-label="Permalink to &quot;条件出现在速度场里而不是事后warp&quot;">​</a></h3><p>若先无条件出图再按 \\(P\\) 去 warp，几何正确但遮挡与新可见面无法生成。整流流把 \\(c\\)（含查询位姿与参考潜变量）放进 \\(v_\\theta(\\cdot,t,c)\\)，每一步去噪都在问「这个 \\(P\\) 下像素该是什么」，包括从未见过的背面。这与图形学的重投影+空洞填充不同：空洞由生成填，而不是只靠插值。少步时 \\(c\\) 若弱，速度场会走向平均场景，形变重新出现——这是 <a href="/llm/rtfm-morphing">RTFM 形变</a> 在 Atlas 内核上的对应物。</p><p><span class="marginnote">ODE 步数与自回归元素数是两笔账。加长视频是多元素，提高单帧清晰度往往是多步或更好的 VAE。把「一分钟」写成「扩散走了一分钟」是范畴错误。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>自回归与整流流接在元素边界上：抽到下一个元素是图像时，才在该元素的 \\(z\\) 上跑 ODE；文本元素仍可以是离散。于是 KV 缓存的是已经完成的元素（及其注意力键值），不是 ODE 的中间 \\(t\\)。这与 LLM 兼容：服务框架看到的是变长序列，扩散是元素内部的循环。分离式 serving、cache-aware 路由之所以「可以沿用」，依据是这层接口，而不是已经公开了一张 Atlas 集群图。</p><p>空间条件 \\(c\\) 在每一步 \\(t\\) 注入，使去噪过程始终看见参考视与查询位姿。少步时，若 \\(c\\) 弱（文本运镜、无 \\(P\\)），ODE 会抄近路到平均外观，表现为形变。原生相机与空间锚定的意义，有一部分就是给 \\(v_\\theta\\) 一条不能忽略的几何条件，减少少步积分的歧义。即便如此，整流流不创造三维元素：它只是在给定条件下运输概率质量。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>没有 Atlas 的训练曲线、步数–FID 表、蒸馏比。1440p 一分钟是展示，不说明 ODE 步数。VAE 会丢掉解码器补不回的高频，再强的流也回不到那些细节；深度与 splat 写出还依赖深度作为元素类型，不只依赖 RGB 潜空间。DDPM 文献里的很多稳定性技巧（学习方差、v-prediction）是否用在 Atlas 上，未知。</p><p>引用时分开三层：Lipman et al., <em>Flow Matching for Generative Modeling</em>, 2023（流匹配；直线路径与整流流叙述同属这一脉络）；Rombach et al., <em>High-Resolution Image Synthesis with Latent Diffusion Models</em>, 2022；Ho et al., DDPM, 2020；Ho &amp; Salimans, CFG。Atlas 自身只应引用 World Labs 2026 年博客，不要给它编造论文编号。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Atlas 的生成内核是潜空间里的整流流：VAE 压维，速度场把噪声运到数据。</li><li>直线条件路径使少步积分与蒸馏成为合理的速度/质量旋钮。</li><li>这与 DDPM 的离散链、LDM 的潜空间、CFG 的条件外推是可组合的家族工具，不是 Atlas 独有公式。</li><li>自回归发生在元素之间，ODE 发生在元素之内，故能接 LLM 式 KV。</li><li>流不替代空间位姿：条件弱时少步更易形变。</li><li>出处：Lipman et al. 2023；Rombach LDM；Ho DDPM；CFG（Ho &amp; Salimans）。Atlas 实现以官方博客为准，无 World Labs arXiv。</li></ul>',14))])}const u=r(m,[["render",c]]);export{b as __pageData,u as default};
